  FT["PH-H2992"] = {"id":"PH-H2992","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3556_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加东明多洛省省医院床位的法案","en":"An Act to Increase the Bed Capacity of the Mindoro Oriental Provincial Hospital","orig":"An Act to Increase the Bed Capacity of the Mindoro Oriental Provincial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3556","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3556_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2992-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Mindoro Oriental Provincial Hospital is hereby increased from seventy-five beds to one hundred beds."}},{"id":"PH-H2992-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The financing of this hospital shall be in accordance with the Hospital Financing Act."}},{"id":"PH-H2992-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Increase the Bed Capacity of the Mindoro Oriental Provincial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2993"] = {"id":"PH-H2993","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3557_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Purchase of Hospital Furnishings and Equipment of the New National Orthopedic Hospital","orig":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Purchase of Hospital Furnishings and Equipment of the New National Orthopedic Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3557","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3557_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2993-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the purchase of hospital furnishings and equipment of the new National Orthopedic Hospital."}},{"id":"PH-H2993-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H2994"] = {"id":"PH-H2994","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3558_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在卡加延省Claveria市镇设立农村职业中学，名称为Claveria农村职业中学，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Rural and Vocational High School in the Municipality of Claveria, Province of Cagayan, to be Known as the Claveria Rural and Vocational High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Rural and Vocational High School in the Municipality of Claveria, Province of Cagayan, to be Known as the Claveria Rural and Vocational High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3558","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3558_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2994-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Public Schools, a rural and vocational high school in the Municipality of Claveria, Province of Cagayan, to be known as the Claveria Rural and Vocational High School."}},{"id":"PH-H2994-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-four. Thereafter, such sum as may be needed for the operation and maintenance of said school shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2994-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Rural and Vocational High School in the Municipality of Claveria, Province of Cagayan, to be Known as the Claveria Rural and Vocational High School, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2995"] = {"id":"PH-H2995","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3559_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授权拨款30万比索在卡加延-德奥罗市建造邮局大楼的法案","en":"An Act Authorizing the Appropriation of Three Hundred Thousand Pesos for the Construction of a Post Office Building in the City of Cagayan De Oro","orig":"An Act Authorizing the Appropriation of Three Hundred Thousand Pesos for the Construction of a Post Office Building in the City of Cagayan De Oro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3559","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3559_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2995-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three hundred thousand pesos, or so much thereof as may be necessary, is hereby authorized to be appropriated out of any funds of the National Treasury, for the construction of a post office building in the City of Cagayan de Oro."}},{"id":"PH-H2995-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The building shall be constructed in accordance with the specifications of the Bureau of Posts, duly approved by the Department of Public Works and Communications: Provided, That this building shall house the post office and other allied offices for the City of Cagayan de Oro."}},{"id":"PH-H2995-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Appropriation of Three Hundred Thousand Pesos for the Construction of a Post Office Building in the City of Cagayan De Oro","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2996"] = {"id":"PH-H2996","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3560_1963.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在苏禄省Tandubas市镇设立急诊医院并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Tandubas, Province of Sulu, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Tandubas, Province of Sulu, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3560","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3560_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2996-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Health, an emergency hospital in the Municipality of Tandubas, Province of Sulu, to be known as the Tandubas Emergency Hospital."}},{"id":"PH-H2996-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H2996-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-four. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2996-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Tandubas, Province of Sulu, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2997"] = {"id":"PH-H2997","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3561_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为伊洛伊洛省增设一名助理省检察官，为此修订《修订行政法典》第1674条（经修正）的法案","en":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Iloilo, Amending for This Purpose Section Sixteen Hundred Seventy-Four of the Revised Administrative Code, as Amended","orig":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Iloilo, Amending for This Purpose Section Sixteen Hundred Seventy-Four of the Revised Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3561","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3561_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2997-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Revised Administrative Code, as amended, relative to assistant provincial fiscals in the Province of Iloilo, is further amended to read as follows:\n\"Iloilo, nine assistant provincial fiscals;\""}},{"id":"PH-H2997-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Iloilo, Amending for This Purpose Section Sixteen Hundred Seventy-Four of the Revised Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2998"] = {"id":"PH-H2998","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3562_1963.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"促进菲律宾盲人教育的法案","en":"An Act to Promote the Education of the Blind in the Philippines","orig":"An Act to Promote the Education of the Blind in the Philippines"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3562","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3562_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2998-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Public Schools, a residential school for the blind near the City of Manila, which shall be known as the Philippine National School for the Blind. Said school shall furnish instruction to the blind in the elementary level."}},{"id":"PH-H2998-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the establishment of the Philippine National School for the Blind, the School for the Deaf and the Blind in Pasay City shall cease to give instruction to the blind, and all its blind students, its equipment and facilities being used in the instruction of the blind, and members of the faculty teaching the blind shall be transferred to the Philippine National School for the Blind."}},{"id":"PH-H2998-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There shall be established, under the supervision and control of the Director of Public Schools a Teacher-Training Center to train teachers for the blind. The Philippine Normal College shall provide room and other facilities for the said Center."}},{"id":"PH-H2998-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to implement the provisions of this Act."}},{"id":"PH-H2998-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of five hundred thousand pesos to carry out the provisions of this Act for the fiscal year nineteen hundred and sixty-four, including the purchase of site and the construction of buildings for the Philippine National School for the Blind. Thereafter, the amount necessary for the operation and maintenance of the said school and center shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2998-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Promote the Education of the Blind in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2999"] = {"id":"PH-H2999","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3563_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在卡皮斯省President Roxas市镇设立急诊医院并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of President Roxas, Province of Capiz, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of President Roxas, Province of Capiz, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3563","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3563_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2999-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Health, an emergency hospital in the Municipality of President Roxas, Province of Capiz, to be known as the President Roxas Emergency Hospital."}},{"id":"PH-H2999-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-four. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2999-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of President Roxas, Province of Capiz, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3000"] = {"id":"PH-H3000","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3564_1963.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在苏禄省设立两个学校分区的法案","en":"An Act to Provide for Two School Divisions in the Province of Sulu","orig":"An Act to Provide for Two School Divisions in the Province of Sulu"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3564","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3564_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3000-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be two school divisions in the Province of Sulu. The first school division shall comprise all the municipalities on the mainland of Jolo and the surrounding island municipalities of Tonquil, Pangutaran, Pata, Tapul, Cagayan de Sulu, and Turtle Islands, and the second school division shall comprise the rest of the municipalities from Siasi down to the Tawi-Tawi group."}},{"id":"PH-H3000-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Public Schools shall recognize the School Division Office of the Province of Sulu into two school divisions commencing with the school year nineteen hundred sixty-three to nineteen hundred sixty-four, in accordance with the provisions of this Act."}},{"id":"PH-H3000-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Such sums as may be necessary to carry out the purposes of this Act for the school year nineteen hundred sixty-three to nineteen hundred sixty-four, is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated. The sum necessary for the same purpose in subsequent years shall be included in the General Appropriation Acts."}},{"id":"PH-H3000-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for Two School Divisions in the Province of Sulu","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3001"] = {"id":"PH-H3001","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3565_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1613号共和国法第2条第f款宿务省第（17） III目第45页第（a）项的法案","en":"An Act Amending Item (a), Page 45, Subparagraph (17) III, for the Province of Cebu, Paragraph f, Section Two of Republic Act Numbered Sixteen Hundred Thirteen","orig":"An Act Amending Item (a), Page 45, Subparagraph (17) III, for the Province of Cebu, Paragraph f, Section Two of Republic Act Numbered Sixteen Hundred Thirteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3565","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3565_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3001-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (a), page 45, subparagraph (17) III, paragraph f, Section two of Republic Act Numbered Sixteen hundred thirteen, is hereby amended to read as follows:\n\"(a) Talisay Municipal Hall Construction ₱75,000.00\""}},{"id":"PH-H3001-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Item (a), Page 45, Subparagraph (17) III, for the Province of Cebu, Paragraph f, Section Two of Republic Act Numbered Sixteen Hundred Thirteen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3002"] = {"id":"PH-H3002","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3566_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Siasi市","en":"An Act Establishing a Fishery School at Lapak, Municipality of Siasi, Province of Sulu, to be Known as the Lapak National School of Fisheries and Authorizing the Appropriation of the Sum of Five Hundred Thousand Pesos for This Purpose","orig":"An Act Establishing a Fishery School at Lapak, Municipality of Siasi, Province of Sulu, to be Known as the Lapak National School of Fisheries and Authorizing the Appropriation of the Sum of Five Hundred Thousand Pesos for This Purpose"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 3566","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3566_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3002-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established at the Lapak Agricultural School, Lapak, Municipality of Siasi, Province of Sulu, site of the fishery school, to be known as the Lapak National School of Fisheries. The Director of Public Schools shall promulgate rules and regulations to implement this Act. The present physical facilities such as buildings, site, books, office and classroom furniture, equipment and such other improvements and facilities of the Lapak Agricultural School are to be transferred without cost to the Lapak National School of Fisheries. The principal, teachers and all other personnel are to be retained by the Lapak Agricultural School at Tarawakan, Sulu, new site of this school. The fishery school in conjunction with its operation shall maintain a research pearl culture station to conduct studies and researches on the propagation and cultivation of pearl."}},{"id":"PH-H3002-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated for the operation and maintenance of this school and shall thereafter be included in the annual General Appropriation Acts."}},{"id":"PH-H3002-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H3003"] = {"id":"PH-H3003","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3567_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Narvacan市","en":"An Act Creating a Branch Office of the Register of Deeds of the Province of Ilocos Sur, with Permanent Station at the Municipality of Narvacan, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating a Branch Office of the Register of Deeds of the Province of Ilocos Sur, with Permanent Station at the Municipality of Narvacan, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3567","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3567_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3003-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds of the Province of Ilocos Sur, with permanent station at the Municipality of Narvacan. which shall be under the immediate control and supervision of a deputy register of deeds to be appointed by the Secretary of Justice. The said deputy register of deeds shall be class III under WAPCO classification and shall receive such compensation in the range now provided by laws and regulations. He shall be assisted by such additional personnel, likewise appointed by the Secretary of Justice, as may be necessary to carry out the duties appurtenant to the said branch office."}},{"id":"PH-H3003-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos, or as much thereof as may be necessary is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act. Thereafter, such sum necessary for the same purpose shall be included in the annual General Appropriation Acts."}},{"id":"PH-H3003-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H3004"] = {"id":"PH-H3004","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3568_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Initao市","en":"An Act Converting the Initao Forest Reserve Located in the Municipality of Initao, Province of Misamis Oriental, into a National Park, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Initao Forest Reserve Located in the Municipality of Initao, Province of Misamis Oriental, into a National Park, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 3568","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3568_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3004-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Initao Forest Reserve located in the Municipality of Initao, Province of Misamis Oriental, is hereby converted into a national park to be known as the Initao National Park."}},{"id":"PH-H3004-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to defray the expenses for development, beautification, and construction of rest houses and other facilities within the vicinity of the Initao National Park."}},{"id":"PH-H3004-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H3005"] = {"id":"PH-H3005","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3569_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将宿务省第一国会选区划设为独立工程区的法案","en":"An Act Constituting the First Congressional District of the Province of Cebu into a Separate Engineering District","orig":"An Act Constituting the First Congressional District of the Province of Cebu into a Separate Engineering District"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3569","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3569_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3005-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the first congressional district of the Province of Cebu is hereby constituted into a separate engineering district to be known as the Second Engineering District of the Province of Cebu, with its office at the City of Danao.\nThe district engineer for said engineering district shall be appointed in accordance with existing laws."}},{"id":"PH-H3005-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the First Congressional District of the Province of Cebu into a Separate Engineering District","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3006"] = {"id":"PH-H3006","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3570_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第3247号共和国法（授予Cagayan Electric Power and Light Co.，Inc.在卡加延德奥罗市及其郊区的特许经营权）的法案，并予公布施行","en":"An Act Amending Republic Act Numbered Thirty-Two Hundred Forty Seven, Entitled “An Act Granting the Cagayan Electric Power and Light Co., Inc. a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the City of Cagayan De Oro and its Suburbs”","orig":"An Act Amending Republic Act Numbered Thirty-Two Hundred Forty Seven, Entitled “An Act Granting the Cagayan Electric Power and Light Co., Inc. a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the City of Cagayan De Oro and its Suburbs”"},"level":"law","status":"active","topics":["investment","energy"],"docNumber":"Republic Act No. 3570","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3570_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3006-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and three of Republic Act Numbered Thirty-two hundred forty-seven is hereby amended to read as follows:\n\"Sec. 1. Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, there is granted to the Cagayan Electric Power and Light Co., Inc., a corporation duly organized and existing under the laws of the Republic of the Philippines, for a period of fifty years from the date of approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and/or distributing electric light, heat and/or power for sale within the municipalities of Tagoloan and Opol, both in the Province of Misamis Oriental, and in the City of Cagayan de Oro and its suburbs. The grantee shall further have the right and privilege to install, lay and maintain on all streets, public thoroughfares, bridges and public places within said limits, poles, wires, transformers, capacitors, overhead protective devices, and pole line hardware, and other equipment necessary for the safe distribution of electric current to the public.\n\"Sec. 3. In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to three per centum of the gross earnings for electric current sold under this franchise, of which two per centum goes into the National Treasury and one per centum goes into the treasury of the Municipality of Tagoloan, the Municipality of Opol, and Cagayan de Oro City, as the case may be: Provided , That said franchise tax of three per centum of the gross earnings shall be in lieu of all taxes and assessments of whatever authority upon privileges, earnings, income, franchise, and poles, wires, transformers, and insulators of the grantee from which taxes and assessments the grantee is hereby expressly exempted.\""}},{"id":"PH-H3006-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of the same Act is hereby amended to read as follows:\n\"An Act granting the Cagayan Electric Power and Light Co., Inc., a franchise to install, operate, and maintain an electric light, heat and power system in the municipalities of Tagoloan and Opol and in the City of Cagayan de Oro and its suburbs.\""}},{"id":"PH-H3006-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963"}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Thirty-Two Hundred Forty Seven, Entitled “An Act Granting the Cagayan Electric Power and Light Co., Inc. a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the City of Cagayan De Oro and its Suburbs”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3007"] = {"id":"PH-H3007","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3571_1963.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"禁止砍伐、毁坏或损伤公共道路旁、广场、公园、校园或其他公共游憩场所已种植或生长中的树木、花卉与灌木或具景观价值植物的法案","en":"An Act to Prohibit the Cutting, Destroying or Injuring of Planted or Growing Trees, Flowering Plants and Shrubs or Plants of Scenic Value Along Public Roads, in Plazas, Parks, School Premises or in Any Other Public Pleasure Ground","orig":"An Act to Prohibit the Cutting, Destroying or Injuring of Planted or Growing Trees, Flowering Plants and Shrubs or Plants of Scenic Value Along Public Roads, in Plazas, Parks, School Premises or in Any Other Public Pleasure Ground"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3571","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3571_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3007-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to promote and conserve the beauty of objects of scenic and ornamental value along public places and help preserve cool, fresh and healthful climate, it is the policy of the Government to cherish, protect and conserve planted or growing trees, flowering plants and shrubs or plants of ornamental value along public roads, in plazas, parks, school premises or in any other public ground."}},{"id":"PH-H3007-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For the purpose of carrying out effectively the provisions of this Act, the Director of Parks and Wildlife shall have the power to create a committee in each and every municipality in the Philippines and shall appoint any civic conscious and well-travelled citizen as chairman, and the municipal mayor, the municipal treasurer, the supervising school teacher, and the municipal health officer, as ex officio members thereof. The Director of Parks and Wildlife shall also have the power to issue and promulgate rules and regulations as may be necessary in carrying out the provisions of this Act.\nThe chairman shall receive compensation of one peso per annum to be paid out of the funds of the city or municipality concerned, and the members shall not receive extra compensation. The Committee shall have the power to implement the rules and regulations issued by the Director of Parks and Wildlife under the provisions of this Act.\nThe Committee shall coordinate with the Director of Parks and Wildlife in the beautification of their respective locality and shall, under its supervision, require school children on Arbor Day to plant trees and flowering plants of useful and scenic value in places provided for in the preceding paragraph."}},{"id":"PH-H3007-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"No cutting, destroying or injuring of planted or growing trees, flowering plants and shrubs or plants of scenic value along public roads, in plazas, parks, school premises or in any other public ground shall be permitted save when the cutting, destroying or injuring of same is necessary for public safety, or such pruning of same is necessary to enhance its beauty and only upon the recommendation of the committee mentioned in the preceding section, and upon the approval of the Director of Parks and Wildlife. The cutting, destroying or pruning shall be under the supervision of the committee."}},{"id":"PH-H3007-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any person who shall cut, destroy or injure trees, flowering plants and shrubs or plants of scenic value mentioned in the preceding sections of this Act, shall be punished by prision correccional in its minimum period to prision mayor in its minimum period."}},{"id":"PH-H3007-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, Acts, parts of Acts, executive orders, and administrative orders or regulations inconsistent with the provisions of this Act, are hereby repealed."}},{"id":"PH-H3007-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Prohibit the Cutting, Destroying or Injuring of Planted or Growing Trees, Flowering Plants and Shrubs or Plants of Scenic Value Along Public Roads, in Plazas, Parks, School Premises or in Any Other Public Pleasure Ground","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3008"] = {"id":"PH-H3008","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3572_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for the Construction of Dewey Boulevard Extension to Cavite City","orig":"An Act Appropriating Funds for the Construction of Dewey Boulevard Extension to Cavite City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3572","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3572_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3008-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of forty million pesos or so much thereof as may be necessary is appropriated out of the proceeds of bonds issued under Republic Act Numbered One thousand for the construction of Dewey Boulevard extension from the Rizal-Cavite Boundary to Cavite City."}},{"id":"PH-H3008-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The extension of Dewey Boulevard to be constructed under the provisions of this Act is declared as a Limited Access Highway."}},{"id":"PH-H3008-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H3009"] = {"id":"PH-H3009","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3573_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在卡加延省Ballesteros市镇设立急诊医院，名称为Ballesteros急诊医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Ballesteros, Province of Cagayan, to be Known as the Ballesteros Emergency Hospital and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Ballesteros, Province of Cagayan, to be Known as the Ballesteros Emergency Hospital and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3573","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3573_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3009-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, an emergency hospital in the Municipality of Ballesteros, Province of Cagayan, to be known as the Ballesteros Emergency Hospital."}},{"id":"PH-H3009-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-four. Therefore, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriation Acts."}},{"id":"PH-H3009-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Ballesteros, Province of Cagayan, to be Known as the Ballesteros Emergency Hospital and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
