  FT["PH-H3013"] = {"id":"PH-H3013","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3577_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将邦板牙省弗洛里达布兰卡市镇古塔德小学的名称变更为Atanacio Pangan小学的法案","en":"An Act Changing the Name of the Gutad Elementary School in the Municipality of Floridablanca, Province of Pampanga, to Atanacio Pangan Elementary School","orig":"An Act Changing the Name of the Gutad Elementary School in the Municipality of Floridablanca, Province of Pampanga, to Atanacio Pangan Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3577","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3577_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3013-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Gutad Elementary School in the Municipality of Floridablanca, Province of Pampanga, is hereby changed to Atanacio Pangan Elementary School."}},{"id":"PH-H3013-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Gutad Elementary School in the Municipality of Floridablanca, Province of Pampanga, to Atanacio Pangan Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3014"] = {"id":"PH-H3014","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3578_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将奎松省布埃纳维斯塔市镇布埃纳维斯塔小学的名称变更为Doña Asuncion Palma Guevara小学的法案","en":"An Act Changing the Name of the Buenavista Elementary School in the Municipality of Buenavista, Province of Quezon, to Doña Asuncion Palma Guevara Elementary School","orig":"An Act Changing the Name of the Buenavista Elementary School in the Municipality of Buenavista, Province of Quezon, to Doña Asuncion Palma Guevara Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3578","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3578_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3014-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Buenavista Elementary School in the Municipality of Buenavista, Province of Quezon, is hereby changed to Doña Asuncion Palma Guevara Elementary School."}},{"id":"PH-H3014-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Buenavista Elementary School in the Municipality of Buenavista, Province of Quezon, to Doña Asuncion Palma Guevara Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3015"] = {"id":"PH-H3015","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3579_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为北伊罗戈省增设助理省检察官职位，为此修订《修订行政法典》第1674条（经修正）的法案","en":"An Act Creating Additional Positions of Assistant Provincial Fiscals in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Revised Administrative Code, as Amended","orig":"An Act Creating Additional Positions of Assistant Provincial Fiscals in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Revised Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3579","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3579_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3015-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred and seventy-four of the Revised Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Ilocos Norte, is further amended to read as follows:\n\"Ilocos Norte, six assistant provincial fiscals.\""}},{"id":"PH-H3015-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Additional Positions of Assistant Provincial Fiscals in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Revised Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3016"] = {"id":"PH-H3016","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3580_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"推进审计总署现代化计划并为此提供资金的法案","en":"An Act to Further the Modernization Program of the General Auditing Office and to Make Funds Available for This Purpose.","orig":"An Act to Further the Modernization Program of the General Auditing Office and to Make Funds Available for This Purpose."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3580","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3580_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3016-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Auditor General is hereby authorized to pursue further its modernization program by reorganizing\" and expanding the Program Audit Department and the Audit Methods and Training Staff of the General Auditing Office to include in their operations the program audit of local governments, development of auditing personnel, and improvement of auditing, accounting, and other fiscal procedures and practices that are the responsibilities of the General Auditing Office under existing laws, and for this purpose there is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the amount of throe hundred sixty-four thousand three hundred four pesos, as follows:\nI.-PERSONAL SERVICES\nA. For new positions:\nPROGRAM AUDIT DEPARTMENT\nOffice of the Manager\nOne Chief Supervising Auditor at P8,400 per annum P8,400 One Auditor at P5,100 per annum , 5,100 One Stenographer at P3,720 per annum 3,720 One Driver at P2,400 per annum 2,400 One Janitor at P1,680 per annum 1,680 One Laborer at PI,680 per annum 1,680 Program Audit Division for Local Governments One Chief Supervising Auditor at P8,400 per annum 8,400 One Auditor at P7.800 per annum 7,800 One Auditor at P6.888 per annum 6,888 One Auditor at P5,700 per annum 5,700 One Auditor at P5,100 per annum 5,100 Two Auditors at P4,200 each per annum 8,400 Two Auditing Examiners at P8,600 each per annum 7,200 Two Auditing Examiners at P3,300 each per annum 6,600 Program Audit Division I One Chief Supervising Auditor at P8,400 per annum 8,400 One Auditor at P7,800 per annum 7,800 One Auditor at P6,888 per annum 6,888 One Auditor at P5,700 per annum 5,700 One Auditor at P5,100 per annum 5,100 One Auditor at P4,200 per annum 4,200 One Auditing Examiner at P3,600 per annum 3,600 One Auditing Examiner at P3,300 per annum 3,300 Program Audit Division II One Chief Supervising Auditor at P8,400 per annum 8,400 One Auditor at P7,800 per annum 7,800 One Auditor at P5,700 per annum 5,700 One Auditor at P5,100 per annum 5,100 One Auditor at P4,200 per annum 4,200 One Auditing Examiner at P3,600 per annum 3,600 One Auditing Examiner at P3,300 per annum 3,300 Income Examination Division Chief Supervising Auditor at P8,400 per annum 8,400 One Auditor at P6,888 per annum 6,888 One Auditor at P5,700 per annum 5,700 One Auditor at P5,100 per annum 5,100 One Auditor at P4,200 per annum 4,200 One Auditing Examiner at P3,600 per annum 3,600 One Auditing Examiner at P3,300 per annum 3,300 AUDIT METHODS AND TRAINING STAFF Training Branch Two Auditors at P6,000 each per annum 12,000 One Clerk-Typist at P2,400 per annum 2,400 One Duplicating Equipment Operator at P2,400 per annum 2,400 One Janitor at P1,680 per annum 1,680 One Laborer at P1,680 per annum 1,680 Methods and Systems Branch Three Auditors at P6,000 each per annum 18,000 Three Auditors at P4,800 each per annum 14,400 One Clerk-Typist at P2,400 per annum 2,400 Research Branch Two Auditors at 1M.800 each per annum 9,600 One Clerk-Typist at P2,400 per annum 2,400 ______________ Total for new positions P266,304 ______________\nB. Government share in employees' life and retirement insurance premiums 26,000 ______________ Total for Personal Services P292,304 ______________ II.-MAINTENANCE AND OTHER OPERATING EXPENSES Travel expenses P30,000 Rentals 12,000 Sundries 10,000 ______________ Total for Maintenance and other Operating Expenses P52,000 ______________ III.-FURNITURE AND EQUIPMENT Equipment Outlay P20,000 ______________ IV.-SUMMARY Total for personal services P292,304 Total for maintenance and other operating expenses 52,000 Total for furniture and equipment 20,000 ______________ Total Appropriation P364,304 ______________"}},{"id":"PH-H3016-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum necessary for the succeeding fiscal years shall be included in the appropriations for the General Auditing Office in the annual General Appropriation Acts."}},{"id":"PH-H3016-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect on July first, nineteen hundred sixty-three.\nApproved, June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further the Modernization Program of the General Auditing Office and to Make Funds Available for This Purpose.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3017"] = {"id":"PH-H3017","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3581_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授予Narciso Padilla先生菲律宾国籍并使其成为菲律宾公民的法案","en":"An Act Granting Philippine Citizenship to Mr. Narciso Padilla","orig":"An Act Granting Philippine Citizenship to Mr. Narciso Padilla"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3581","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3581_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3017-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mr. Narciso Padilla is hereby granted Philippine citizenship with all the rights, privileges and prerogatives appurtenant thereto."}},{"id":"PH-H3017-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philippine Citizenship to Mr. Narciso Padilla","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3018"] = {"id":"PH-H3018","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3582_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将卡加延省卡加延省立医院床位由50张增至75张并授权为此拨款的法案","en":"An Act to Increase the Bed Capacity of the Cagayan Provincial Hospital in the Province of Cagayan from Fifty to Seventy-Five Beds and to Authorize the Appropriation of Funds for the Purpose","orig":"An Act to Increase the Bed Capacity of the Cagayan Provincial Hospital in the Province of Cagayan from Fifty to Seventy-Five Beds and to Authorize the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3582","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3582_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3018-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Cagayan Provincial Hospital in the Province of Cagayan is hereby increased from fifty to seventy-five beds."}},{"id":"PH-H3018-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In addition to the appropriations for the said hospital under existing law, the sum of two hundred ninety-six thousand seven hundred twenty-one pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance thereof."}},{"id":"PH-H3018-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Increase the Bed Capacity of the Cagayan Provincial Hospital in the Province of Cagayan from Fifty to Seventy-Five Beds and to Authorize the Appropriation of Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3019"] = {"id":"PH-H3019","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3583_1963.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授予 Ilocos Norte 电力公司在北伊罗戈省 Laoag 与 San Nicolas 市镇安装、维护和运营电灯、热力与动力系统并销售分销的特许权","en":"An Act Granting the Ilocos Norte Electric Company a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipalities of Laoag and San Nicolas, Both in the Province of Ilocos Norte, and to Sell and Distribute Light, Heat and Power Therein","orig":"An Act Granting the Ilocos Norte Electric Company a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipalities of Laoag and San Nicolas, Both in the Province of Ilocos Norte, and to Sell and Distribute Light, Heat and Power Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 3583","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3583_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3019-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, there is granted to the Ilocos Norte Electric Company, for a period of fifty years from the approval of this Act, the right, privilege and authority to install, maintain and operate electric light, heat and power system for the purpose of generating and distributing electric light, heat and power for sale in the municipalities of Laoag and San Nicolas, both in the Province of Ilocos Norte, and to collect and charge a schedule of prices, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission; Provided, That electric and power services to the Ablan Memorial and the Ilocos Norte Waterworks reservoir at Ermita Hill including all government buildings established in said area, be charged only at costs."}},{"id":"PH-H3019-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the National Power Corporation shall have established its lines in the areas adjacent to or over the territory covered by this franchise, the National Power Corporation may make available its power and heat only after negotiation with and through the Ilocos Norte Electric Company, or with the authority and consent of the grantee. The National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates as approved by the Public Service Commission subject to the exception in the next preceding paragraph."}},{"id":"PH-H3019-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In consideration of this franchise and rights hereby granted, the grantee shall pay into the Treasury of the Philippines a franchise tax equal to two per centum of the gross earnings for electric current sold under this franchise. Provisions of law to the contrary notwithstanding, the franchise tax equal to two per centum of the gross earnings of the grantee as provided for in the original franchises granted by the municipalities of Laoag and San Nicolas, both in the Province of Ilocos Norte, shall be respected. Effective upon the date the original franchise was granted, no other tax upon its capital stock, franchise, right of way, earnings and all other property owned or operated by the grantee under this concession or franchise shall be levied or assessed on the herein grantee except the franchise tax of two per centum of the gross earnings mentioned in the said original franchise."}},{"id":"PH-H3019-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Upon approval of this Act, the municipal franchise granted the Ilocos Norte Electric Company shall terminate and this franchise shall take its place."}},{"id":"PH-H3019-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Ilocos Norte Electric Company a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipalities of Laoag and San Nicolas, Both in the Province of Ilocos Norte, and to Sell and Distribute Light, Heat and Power Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3020"] = {"id":"PH-H3020","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3584_1963.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在东米萨米斯省设立Libertad市镇的法案","en":"An Act Creating the Municipality of Libertad in the Municipality of Misamis Oriental","orig":"An Act Creating the Municipality of Libertad in the Municipality of Misamis Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3584","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3584_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3020-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Libertad, Gimaylan, Lubluban, Dulong, Taytayan and Tangcub are hereby separated from the Municipality of Initao, Province of Misamis Oriental, and constituted into a new municipality to be known as the Municipality of Libertad of the same province."}},{"id":"PH-H3020-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The boundaries of the Municipality of Libertad are as follows:\n\"Beginning at point marked \"1\" on plan, a common point of the municipalities of Gitagum and Initao, thence following the original Gitagum and Initao boundary; S. 39 00’ E, 8,255.00 meters to point \"2\" thence S 17 00’ W, 4,200.00 meters to point \"3\" thence N 39 00’ W, 5,000.00 meters to point \"4\" thence, northwest approximately 6,600.00 meters following a natural waterway to point \"5\", thence, northeast approximately 6,200.00 meters following the coastal stretch to point of beginning.\""}},{"id":"PH-H3020-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first mayor, vice-mayor and councilors of the municipality shall be appointed by the President of the Philippines with the consent of the Commission on Appointments and shall continue in office until their successors shall have been elected in the next election for local officials and shall have qualified."}},{"id":"PH-H3020-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Libertad in the Municipality of Misamis Oriental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3021"] = {"id":"PH-H3021","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3585_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权买卖","en":"An Act Authorizing the Sale, Transfer and Conveyance to the Universal Telecommunications Service, Inc. of the Franchise and All the Properties and Rights Acquired Thereunder Granted to Mr. Anastacio Morales Under Republic Act Numbered Thirty-Two Hundred Forty-Six to Establish, Maintain and Operate Radio Stations for International and Domestic Communications","orig":"An Act Authorizing the Sale, Transfer and Conveyance to the Universal Telecommunications Service, Inc. of the Franchise and All the Properties and Rights Acquired Thereunder Granted to Mr. Anastacio Morales Under Republic Act Numbered Thirty-Two Hundred Forty-Six to Establish, Maintain and Operate Radio Stations for International and Domestic Communications"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 3585","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3585_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3021-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of Republic Act Numbered Thirty-two forty-six, the sale, transfer, and conveyance to the Universal Telecommunications Service, Inc., of the franchise and all the properties and rights acquired thereunder granted to Mr. Anastacio Morales under the said Act, to establish, maintain and operate radio stations for international and domestic communications, is hereby authorized and approved."}},{"id":"PH-H3021-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42"};
  FT["PH-H3022"] = {"id":"PH-H3022","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3586_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"禁止出口遮目鱼苗的法案","en":"An Act Prohibiting the Exportation of Bangus Fry","orig":"An Act Prohibiting the Exportation of Bangus Fry"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 3586","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3586_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3022-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It shall be unlawful for any person, association or corporation to export bangus fry to any foreign country from the date of the approval of this Act."}},{"id":"PH-H3022-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any violation of this Act shall be punished by a fine of not less than one thousand pesos nor more than five thousand pesos or by an imprisonment for not less than one year nor more than five years, or both, at the discretion of the court. In case the violation is committed by an association or corporation, imprisonment when imposed shall be served by the manager thereof and or any other person responsible for said violation."}},{"id":"PH-H3022-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prohibiting the Exportation of Bangus Fry","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3023"] = {"id":"PH-H3023","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3587_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在卡皮斯省若干市镇设立急诊医院的法案","en":"An Act Providing for the Establishment of Emergency Hospitals in Certain Municipalities of the Province of Capiz","orig":"An Act Providing for the Establishment of Emergency Hospitals in Certain Municipalities of the Province of Capiz"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3587","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3587_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3023-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, one emergency hospital in each of the municipalities of Sigma and Tapaz, both in the Province of Capiz."}},{"id":"PH-H3023-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The emergency hospitals established under this Act shall be financed in accordance with the provisions of Republic Act Numbered Nineteen hundred and thirty-nine."}},{"id":"PH-H3023-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of Emergency Hospitals in Certain Municipalities of the Province of Capiz","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3024"] = {"id":"PH-H3024","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3588_1963.html","fetchedAt":"2026-10-06","articleCount":27,"structureMode":"ARTICLE","title":{"zh":"规定选民永久登记并为此推迟原定于 1963 年的选民登记全面更新的法案","en":"An Act to Provide for Permanent Registration of Voters and for This Purpose to Postpone the General Renewal of Registration of Voters Which is Set for Nineteen Hundred Sixty-Three","orig":"An Act to Provide for Permanent Registration of Voters and for This Purpose to Postpone the General Renewal of Registration of Voters Which is Set for Nineteen Hundred Sixty-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3588","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 27 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3588_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3024-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Permanent list of voters. There shall be a permanent list of voters in each city, municipality and municipal district."}},{"id":"PH-H3024-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Who may be registered in the Permanent List of Voters. All persons possessing all the qualifications prescribed for a voter and none of the disqualifications, have the right and duty to be registered in the permanent list of voters of the city, municipality or municipal district wherein they are domiciled and to be included in the precinct book of voters of their corresponding precinct.\nAny person who may not have on the date of his registration the period of domicile required may also be registered upon proof that on the date of the election he shall have such qualification."}},{"id":"PH-H3024-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Election Registrar. There shall be in each city, municipality and municipal district at least one election registrar and a clerk appointed by the Commission on Elections. The salaries for the positions of election registrar and clerk in the city, municipality and municipal district shall be at such rates as may be determined by the position classification to be made by the commission on elections; Provided, however , That in any city, municipality and municipal district having four thousand registered voters or less, the Commission on Elections may at its discretion appoint an election registrar, attach it to another political subdivision for purposes of registration, or appoint the city, municipal or municipal district treasurer as election registrar with additional compensation to be fixed by the Commission on Elections but not to exceed fifty per cent of his salary as treasurer.\nThe city, municipal or municipal district council, as the case may be, shall provide a place for the office of the registrar."}},{"id":"PH-H3024-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Qualification of Election Registrar. Except in the case mentioned in the proviso of Section three hereof, only members of the Philippine Bar may qualify for appointment as election registrar: Provided , That if there are no lawyers available for appointment, graduates of duly recognized schools of law, liberal arts and education who are civil service eligibles may be appointed."}},{"id":"PH-H3024-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Registration of voters. On any date, within sixty days after having acquired the qualifications of a voter, but not later than sixty days before the day of any regular election and not later than thirty days before the day of any special election, a qualified elector shall personally appear before the election registrar of his city, municipality or municipal district wherein he is domiciled and file with him a sworn application for registration in triplicate.\nTo facilitate filing of applications for registration, the election registrar may hold office in any district, barrio or sitio within his jurisdiction, without any travelling allowance, subject to the rules and regulations promulgated by the Commission on Elections. Any person who fails to register within sixty days after having acquired the qualifications of a voter or is registered after said period shall not be qualified to vote in the election immediately following his registration."}},{"id":"PH-H3024-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Application for registration. The sworn application for registration shall contain three specimens of the applicant's signature and his passport or identification photograph, which shall be at the expense of the government if the applicant should so request, and shall state the following:\n(a) name, surname and middle and/or maternal surname:\n(b) place of birth;\n(c) age on his last birthday;\n(d) Philippine citizenship;\n(e) civil status, if married, the name of the spouse;\n(f) profession, occupation or work;\n(g) exact address with the name of the street, the house number or in case there be none, a brief description of the locality and place;\n(h) that he possesses the qualifications required of an elector;\n(i) that he is not disqualified to vote;\n(j) that he is not registered in any other precinct, otherwise, he shall state the precinct number and the city, municipality or municipal district in which he previously registered, and attach thereto his sworn application for the cancellation of such previous registration;\n(k) the prints of all his ten fingers;\n(l) space shall be provided upon the face of the application for the notation of the voting record of the person registered thereon;\n(m) such other information or data which the Commission on Elections may require."}},{"id":"PH-H3024-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Approval or disapproval of application and petition for inclusions. Upon receipt of the sworn application for registration, the election registrar shall set it for hearing, notice of which shall be posted in the municipal building for at least three days before the hearing. On the date of the hearing, the election registrar shall receive whatever evidence that may be submitted for or against the application. The election registrar shall decide within ten days from filing, all applications submitted to him and issue the corresponding identification card to the registered voter.\nIf the election registrar disapproves the application the applicant shall be furnished with a certificate of disapproval wherein the ground for the disapproval shall be stated. The applicant may within fifteen days from the receipt of the certification of disapproval file wit the Justice of the Peace Court or the Court of First Instance of the province a petition for his inclusion, which shall be decided within fifteen days after filing. If the decision is for the inclusion of a voter in the permanent list of voters, the election registrar shall activate the application for registration which has been previously denied, by placing said application in the corresponding precinct book of voters wherein the order of inclusion by the court shall be entered and shall mail or deliver to the voter his identification card. If the decision is adverse, the right of appeal as heretofore granted by existing laws shall be available."}},{"id":"PH-H3024-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Challenge of right to register. Any elector or representative of any political party of the city, municipality or municipal district may appear before the election registrar to oppose or challenge any application for registration stating the ground therefor. The challenge shall be under oath and shall be attached by the election registrar to the application together with proof of notice to the challenger and the voter of the date set for hearing."}},{"id":"PH-H3024-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Publication of application for registration. Within two days from approval or disapproval of any application for registration, the election registrar shall post a notice in the municipal building giving the name and address of the applicant and the date of the application and the action taken on the application."}},{"id":"PH-H3024-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Preparation of precinct Book of Voters. The election registrar shall prepare the precinct book of voters of each precinct which shall consist of all the original copies of the approved applications of voters for registration arranged alphabetically belonging to the same precinct, in a suitable binder or device.\nEach precinct book of voters, before delivery to the board of inspectors shall be duly sealed and certified by the election registrar that the approved applications contained therein, stating the exact number, are complete for the precinct. The election registrar shall deliver this precinct book of voters to the chairman of the board of inspectors at the same time the board takes delivery of its official ballots, for the use of the board during the voting and which shall be returned to the election registrar for his custody at the same time the statement of election returns are delivered. Thirty days before a regular election and ten days before a special election, all precinct book of voters shall be sealed and shall not be available for examination by the public."}},{"id":"PH-H3024-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Permanent list of voters of each city, municipality or municipal district. The approved qualifications of registration contained in all the precinct books of voters of the city, municipality or municipal district shall comprise the permanent list of voters of said city, municipality or municipal district."}},{"id":"PH-H3024-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Provincial Central File of Registered Voters. The duplicate copies of all approved applications for registration shall immediately be sent to the Provincial Central File of Registered Voters which shall be under the custody and supervision of the election registrar assigned in the capital. These applications shall be arranged alphabetically by city, municipality or municipal district and shall be open during office hours to the public with legitimate inquiries for purposes of election."}},{"id":"PH-H3024-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"National Central File of Registered Voters. The triplicate copies of all approved applications for registrations shall immediately be sent to the Commission on Elections. These applications shall be arranged alphabetically by city, municipality or municipal district and shall be open during office hours to the public with legitimate inquiries for purposes of election."}},{"id":"PH-H3024-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Voter's Identification. The voter's identification card shall serve and be considered as document for the identification of each registered voter.\nNo extra copy or duplicate of the voter's identification card shall be prepared and issued except upon authority of the Commission on Elections.\nThe voter's identification card shall be subject at any time to examination, charge or renewal by the Commission on Elections, and any registered voter who fails, without cause, after due notice, to surrender his voter's identification card shall be sufficient ground for its cancellation.\nEach identification card shall bear the name and address of the voter, his age, sex, civil status, occupation, his passport or identification photograph, thumbmark, number of the precinct where he is registered, his signature and the signature of the registrar.\nNo fees shall be collected for the issuance of the voter's identification card."}},{"id":"PH-H3024-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Petition for exclusion of voters and decision thereon. Any elector, representative of a political party or the election registrar of the city, municipality or municipal district may at any time except forty-five days before a regular election and twenty-five days before a special election file with the Justice of the Peace Court or the Court of First Instance of the province a sworn petition for exclusion from the permanent list of voters of any voter on the ground that he is qualified, disabled or illegally registered, which petition shall be decided within fifteen days after filing. The right of appeal as provided for in existing laws shall be available to any interested party.\nThe election registrar upon receipt of the final decision ordering exclusion of a voter shall remove his application from the corresponding precinct book of voters and place said application in the inactive file, wherein the order of exclusion by the court shall be entered.\nThe election registrar shall submit monthly reports or as often as the Commission on Elections may order, of all cancellations made by him pursuant to court orders, so the corresponding action can be taken on the copies of the application in the Provincial Central File and in the Commission on Elections."}},{"id":"PH-H3024-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Cancellation due to death, conviction, and failure to vote in two successive preceding elections. The election registrar shall remove the voter's application for registration from the corresponding precinct book of voters of the following after entering therein the cause for cancellation and shall place them in the inactive file:\n(a) Those who have since died as certified to at the end of each month by the local civil registrar.\n(b) Those who have since been sentenced by final judgment to suffer an imprisonment of not less than one year or found guilty of having violated their allegiance to the Republic of the Philippines as certified to at the end of each month by the clerk of court, the clerk of the municipal court in chartered cities and the justice of the peace.\n(c) Those who did not vote in the two successive preceding regular elections as shown by the voting records of each voter after the holding of an election.\nThe election registrar shall notify by mail or by personal delivery the registered voter of his cancellation and the ground thereof and require the surrender of his voter's identification card. In cases of death, all notices and requirements shall be directed to the voter's next of kin.\nThe name cancelled shall be published on the bulletin board immediately stating the reason for the cancellation and shall be reported to the Commission on Elections and the Provincial Central File together with copies of the certified statements of the local civil registrar, the clerk of court, the clerk of the municipal court of chartered cities and the justice of the peace. The Provincial Central File and the Commission on Elections shall accordingly remove the application for registration of the voters and file them in the inactive file after entering in their re- of notice of the decision by the barrio council concerned registration."}},{"id":"PH-H3024-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Cancellation of previous registration. Any registered voter may request for the cancellation of his registration by personally filing a sworn application for said cancellation with the election registrar, who shall proceed to cancel the same and issue the certificate of cancellation to the voter.\nAny registered voter who has transferred and acquired a new domicile may request for the cancellation of his previous registration as stated in the first paragraph hereof or by sending by registered mail a sworn application for cancellation of registration in duplicate giving his old and new addresses and enclosing his voter's identification card, or by personally filing said sworn application with the election registrar or his new domicile, who upon receipt thereof shall transmit the same, together with the voter's identification card, to the election registrar of the voter's old domicile.\nThe election registrar concerned shall upon receipt of the application for cancellation of registration remove his application for registration from the corresponding book of voters, which shall be placed in the inactive file, and issue the certificate of cancellation to the voter by registered mail or personally. The election registrar shall enter the corresponding notations in the application of registration of said request for cancellation.\nThe election registrar shall preserve all applications for cancellation and shall report all cancellations made by him under this Section to the Commission on Elections and to the Provincial File Center for their corresponding action. The names of voters cancelled shall be posted in the bulletin board for thirty days."}},{"id":"PH-H3024-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Change of Address of Voter in the Same City, Municipality or Municipal District. Any voter who has changed his address in the same city, municipality or municipal district where he is registered shall immediately notify his election registrar not later than forty-five days before any regular election day and thirty days before a special election day. If the change of address involves a change of precinct, the election registrar shall transfer his application of registration from the precinct book of voters of his old precinct to his new precinct. All changes of address shall be reported to the Commission on Elections and the Provincial Filing Center by the election registrar and he shall immediately notify the voter that his change of address has been noted in his application of registration, together with his precinct number, if new."}},{"id":"PH-H3024-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Adjustment of the Precinct Book of Voters in Case of Division or Merger of Precinct. When a precinct is divided into two or more precincts or certain precincts are merged, the election registrar shall accordingly transfer the application for registration of the voters included in the precinct book of voters of the precinct or precincts affected to the corresponding precinct book of voters of the resulting new or adjusted precinct. All adjustments shall be reported to the Commission on Elections and the Provincial Filing Center for their corresponding action. Voters affected by the adjustment of precincts shall be notified by mail of their new precinct resulting from the adjustment."}},{"id":"PH-H3024-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Publication of the Precinct List of Voters. For the purpose of public information and reference only, thirty days before the day of a regular election and ten days before the day of special election, the election registrar shall furnish the candidates, heads of the national political parties in the city, municipality or municipal district, the Provincial Central File and the Commission on Elections a copy of the certified list of the names and addresses of all the voters in each precinct of the city, municipality or municipal district. Changes in this list shall be distributed in the same manner as supplementary lists.\nThe election registrar shall also furnish two certified copies of said precinct list to the poll clerk for posting in the polling place and for the use of the board of inspectors on election day."}},{"id":"PH-H3024-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Canvass to Check Registration. The election registrar shall, subject to the rules and regulations promulgated by the Commission on Elections, conduct such mail check or house to house canvass or both, without traveling allowances, of the voters of any precinct for the purpose of filing exclusion proceedings."}},{"id":"PH-H3024-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Power of election registrar to administer oaths and issue summons. The election registrar shall have the same powers possessed by justices of the peace to administer oaths, to issue subpoena and subpoena duces tecum, to swear witnesses, and to compel witnesses to appear and testify, but if the summons is issued at the instance of any private party, the corresponding fees and the expenses incident thereto, shall be paid in advance by said party."}},{"id":"PH-H3024-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Such sums as are necessary to carry out the objectives and purposes of this Act are hereby authorized to be appropriated. The positions created by this Act as well as the sums needed for operating expenses during each fiscal year shall hereafter be included and provided for in the annual Appropriations Act: Provided, however , That the Commission on Elections is hereby authorized to use such sums available from any savings in the appropriation for the nineteen hundred sixty-three election as it may in its discretion deem necessary for the initial expenses to implement the provisions of this Act."}},{"id":"PH-H3024-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Annulment of registry list. Any precinct book of voters not prepared in accordance with the provisions of this Act, or the preparation of which is effected with fraud, bribery, forgery, impersonation, intimidation, force, or any other similar irregularity may, after due notice and hearing, be annulled by the Commission on Elections."}},{"id":"PH-H3024-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"The preparation of a new list of voters which in accordance with section ninety-five of Republic Act Numbered One hundred eighty as amended by Republic Act Numbered Five hundred ninety-nine is scheduled for the year nineteen hundred sixty-three is hereby postponed: Provided , That the list of voters for the nineteen hundred sixty-three election shall be prepared in accordance with section one hundred one of the revised election code, to the date that this Act takes effect; on which date the list of voters then existing shall be annulled and every voter shall have to register anew; Provided , That the provision of this section shall not be applicable if the date this Act takes effect falls within less than one year from a general election, in which case this section shall take effect on the first day of January next succeeding said general election."}},{"id":"PH-H3024-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Repealing clause. Provisions of the Revised Election Code, and other laws, rules and regulations inconsistent herewith are hereby repealed."}},{"id":"PH-H3024-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Effectivity. This Act shall take effect on January one, nineteen hundred sixty-four: Provided , That section twenty-five hereof shall take effect immediately upon approval of this act.\nApproved: June 22, 1963"}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for Permanent Registration of Voters and for This Purpose to Postpone the General Renewal of Registration of Voters Which is Set for Nineteen Hundred Sixty-Three","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3025"] = {"id":"PH-H3025","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3589_1963.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"修订第 2067 号共和国法，调整国家科学发展委员会、国家科学技术研究所与菲律宾原子能委员会，将科学目的税收豁免及赠款、请求与捐赠特权扩及私立教育机构并为其他目的法案","en":"An Act Amending Republic Act Numbered Two Thousand Sixty-Seven Modifying the National Science Development Board, National Institute of Science and Technology, and the Philippine Atomic Energy Commission, Extending Tax Exemption, Privileges on Grants, Requests and Donations for Scientific Purposes to Private Educational Institutions, and for Other Purposes","orig":"An Act Amending Republic Act Numbered Two Thousand Sixty-Seven Modifying the National Science Development Board, National Institute of Science and Technology, and the Philippine Atomic Energy Commission, Extending Tax Exemption, Privileges on Grants, Requests and Donations for Scientific Purposes to Private Educational Institutions, and for Other Purposes"},"level":"law","status":"active","topics":["tax","energy","education"],"docNumber":"Republic Act No. 3589","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3589_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3025-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Two thousand and sixty-seven is hereby amended by adding a new section to be designated as Section ten-a, after Section ten thereof, to read as follows:\n\"Sec. 10-A. The National Science Development Board shall have final authority to program and utilize exclusively for the support of the activities mentioned in the preceding section, all income, grants, bequests, donations and unexpended balances, which shall compose a Fiduciary Fund to be known as the Science, Engineering and Technology Research Fund.\""}},{"id":"PH-H3025-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"New sections to be designated as Sections twelve-a and twelve-b, are inserted after section twelve of the same Act, to read as follows:\n\"Sec. 12-A. The National Institute of Science and Technology is authorized and empowered to charge reasonable fees in connection with all analyses and tests for purposes of establishing suitable standards, calibration of weights and measures, determination of quality and composition of materials and products, for services as technical determinations where arbitration is sought, and for other analysis and tests. The Institute shall issue rules and regulations establishing scale of fees for above analysis, tests and services and such rules and regulations as the Institute may deem desirable for the collection of such fees.\n\"Sec. 12-B. All income, donations, grants, bequests, and unexpended balances of the National Institute of Science and Technology shall accrue to a Fiduciary Fund, to be known as the Research Foundation Fund, which shall be expended by the Commissioner thereof solely for scientific researches and investigations in the field of conventional science upon the approval and final authority of the Board, the provisions of existing laws to the contrary notwithstanding.\""}},{"id":"PH-H3025-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section sixteen of the same Act is hereby amended to read as follows:\n\"Sec. 16. There is hereby created the Philippine Atomic Energy Commission hereinafter referred to as the Commission, which shall be under the supervision of the Board, with the following functions, powers and duties:\n\"(1) To establish or cause the establishment of laboratories for nuclear research training;\n\"(2) To conduct or cause the performance of research and development relating to:\n\"(a) nuclear processes and techniques;\n\"(b) the theory of atomic energy, \"(c) processes, materials and devices used in the production of atomic energy.\n\"(d) the utilization of special nuclear material and other radioactive material for commercial, industrial, medical, biological, agricultural or other peaceful purposes;\n\"(3) To approve and facilitate the procurement of radioactive material and instrument for use in nuclear laboratories;\n\"(4) To study and evaluate project proposals on nuclear research from public and private sectors, and to recommend necessary technical, financial and other appropriate assistance thereto;\n\"(5) To coordinate the work of research entities and government agencies instrumentalities on nuclear science;\n\"(6) To keep posted on nuclear research projects and activities financed or assisted under this Act;\n\"(7) To represent the Philippines in conference related to atomic energy and its application;\n\"(8) To recommend deserving citizens for training, government and private grants and scholarships in the Philippines and abroad in nuclear science; and \"(9) To render annual reports and such special reports as may be requested by the Board.\""}},{"id":"PH-H3025-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"New Sections to be designated as Sections sixteen-a and sixteen-b are inserted after Section sixteen of the same Act, to read as follows:\n\"Sec. 16-A. No person may manufacture, produce, transfer, acquire, own, possess, import or export any radioactive material except in pursuance of a license issued in accordance with this Act.\n\"The Commission is hereby authorized to regulate and license the acquisition, distribution, and use of radioactive material and for the purpose issue and promulgate such rules, regulations or orders as may be necessary depending upon the degree or importance to the health and safety of the public or to the national defense and security, of the physical characteristics, quantities and the intended use of the radioactive materials.\n\"The Commission shall likewise issue such rules and regulations establishing such standards and instructions to govern the shipments, possession, and use of radioactive materials, and such other rules and regulations, as the Commission may deem desirable, to protect health, minimize danger to life and property, promote the national defense and security or otherwise protect the general public.\n\"The Commission is authorized and empowered to charge reasonable fees in connection with the issuance of licenses; Provided, However, That such fees shall not exceed the reasonable cost of regulating and licensing the activities as provided herein.\n\"The rules and regulations of the Commission shall take effect upon the publication thereof in the Official Gazette.\"\n\"Sec. 16-B. The Commission may sell, lease or otherwise dispose of such radioactive material, as it owns or possess, with or without charge; Provided, However, That the Commission in fixing a charge for radioactive material distributed by it shall establish such charge, on an equitable basis, as in the opinion of the Commission will (a) provide reasonable compensation to the Government for such material, and (b) will encourage research and development: Provided, further, That the Commission may waive any charge depending on whether the licensee is a non-profit of eleemosynary institution and on the purposes for which the radioactive material shall be used.\""}},{"id":"PH-H3025-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section twenty-three of the same Act is hereby amended to read as follows:\n\"Sec. 23. The Board and its agencies as well as the University of the Philippines are hereby authorized and empowered to receive grants, bequests, and donations made or given for the purpose of aiding scientific and technological investigations or establishing scholarship or professional chairs in the fields of science, engineering and technology. Such grants, bequests and donations as well as those received by public or recognized private educational institutions, shall be tax exempt and deductible from the income tax returns of the donor upon certification of the Board, or the University of the Philippines in case it is the donee, that said grants, bequests and donations are dedicated to the purpose above-mentioned, any provision of law, rule or regulation to the contrary notwithstanding."}},{"id":"PH-H3025-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section twenty-four of Republic Act Numbered Two thousand sixty-seven is hereby amended to read as follows:\n\"Sec. 24. The Board shall promote and, in its discretion, assist in the establishment of private foundations for scientific advancements as well as specific research and development projects by private individuals, firms and institutions. All funds contributed to the support and maintenance of such foundations and their projects as well as specific research and development projects undertaken by private individuals and educational institutions, shall be tax-exempt and deductible from the donor’s income tax returns, upon certification by the Board that such foundations and funds are dedicated to scientific pursuits. All income of whatever kind and character which such foundations may derive from any of their properties, real or personal, or from their investments shall also be tax exempt.\""}},{"id":"PH-H3025-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A new section is hereby inserted after Section twenty-four of the same Act, to read as follows:\n\"Sec. 24-A. Any provision of existing laws to the contrary notwithstanding, apparatus, instruments, utensils, equipment, and materials may be imported into the Philippines, whether or not foreign exchange has been allocated by the Central Bank for the payment of such importations, free from all taxes and duties, upon certification of the National Science Development Board that such articles are imported solely for scientific and technological research and development and not for barter, sale or hire: Provided, However, That in case such articles are subsequently conveyed or transferred to other parties for a pecuniary consideration, taxes and duties shall be collected thereon at double the rate provided for under existing laws, payable by the transferor; Provided, further, That the Board shall promulgate the rules and regulations to implement this provision.\""}},{"id":"PH-H3025-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section twenty-five of the same Act is hereby amended so as to read as follows:\n\"Sec. 25. Any person who evades or defeats or attempts to evade or defeat, in any manner, any tax imposed by law by availing himself of the provisions of Section twenty-three or twenty-four hereof through fraud or misrepresentation or violates the rules and regulations promulgated by the Board under this Act shall be punished by a fine of not more than four thousand pesos or imprisonment for not more than one year or both, in the discretion of the Court.\n\"In case the violator is a corporation or association the penalty shall be a fine of not more than ten thousand pesos, without prejudice to the criminal responsibility of the member, officer or employee thereof committing such violation.\n\"Any person who violates any provision of the rules, regulations or orders of the Commission issued pursuant to the provisions of this Act shall be punished by a fine of not more than one thousand pesos or imprisonment for not more than six months, or both, in the discretion of the court.\n\"In case the violator is a corporation or association the penalty shall be a fine of not more than twenty thousand pesos, without prejudice to the criminal responsibility of the officer, member, or employee thereof committing such violation.\""}},{"id":"PH-H3025-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The same Act is hereby amended by adding after Section twenty-six thereof a new section to be known as Section twenty-six-a, to read as follows:\n\"Sec. 26-A The restrictive provisions of Section thirty of Republic Act Numbered Two thousand two hundred and sixty and the law on automatic compulsory retirement, as provided for in Section twelve (c) of Commonwealth Act Numbered One hundred eighty-six, as amended, shall not apply to scientists and researchers appointed and working as such: Provided, However, That the appointing authority concerned may terminate the services of said scientists and researchers at any time after reaching the compulsory retirement age.\""}},{"id":"PH-H3025-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The same Act is hereby amended by adding a new section after Section twenty-seven thereof to be known as Section twenty-seven-a, to read as follows:\n\"Sec. 27-A. There shall be under the administration and control of the Commission on Fiduciary Fund to be known as the Atomic Energy Research Fund which shall accrue and pertain all the fees and charges imposed and collected by the Commission, all income, donations, bequests, grants, and unexpended balance of the Commission, which shall not, any provisions of law to the contrary notwithstanding, revert to the General Fund. The Atomic Energy Research Fund shall be devoted to and disposed of exclusively for the purpose of carrying out the research and development functions of the Commission as provided in Section sixteen of this Act, upon the approval and final authority of the Board.\""}},{"id":"PH-H3025-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section twenty-eight of the same Act is hereby amended to read as follows:\n\"Sec. 28. Funds appropriated for the Board and its agencies shall remain available for obligation, for expenditure, and for obligation and expenditure, until expended.\""}},{"id":"PH-H3025-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section thirty-two of the same Act is hereby amended to read as follows:\n\"Sec. 32. This Act repeals Republic Act Numbered One thousand six hundred and six, except Section three thereof which shall continue in force as amended by Section twenty-seven hereof, Republic Act Numbered One thousand eight hundred and fifteen, except Section ten thereof which shall continue in force as amended by Section twenty-seven hereof, and such other Acts or parts of Acts which are inconsistent herewith."}},{"id":"PH-H3025-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The same Act is hereby amended by adding a new section to be known as Section thirty-three to read as follows:\n\"Sec. 33. For purposes of this Act and unless otherwise indicated in the committee terms herein enumerated shall have the following meanings;\n\"Agencies\"— means the National Institute of Science and Technology and the Philippine Atomic Energy Commission;\n\"Radioactive material\"— means any material which spontaneously gives off ionizing radiation;\n\"Source material\"— means uranium, thorium or any other material which is determined by the Commission to be source materials or ores containing one or more of the foregoing materials in such concentration as the Commission may by regulation determine from time to time;\n\"Special nuclear materials\"— means plutonium, uranium, or any other material in sufficient quantity which the Commission determines to be capable of releasing substantial quantities of energy through nuclear chain reaction of the material.\""}},{"id":"PH-H3025-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section thirty-three of the same Act is hereby redesignated as Section thirty-four."}},{"id":"PH-H3025-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Two Thousand Sixty-Seven Modifying the National Science Development Board, National Institute of Science and Technology, and the Philippine Atomic Energy Commission, Extending Tax Exemption, Privileges on Grants, Requests and Donations for Scientific Purposes to Private Educational Institutions, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
